def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    opp_pressures = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                b = float(bid)
                prev_bids.append(b)
                req = float(opp.get('water_requirement', WATER_REQ))
                sal = float(opp.get('daily_salary', DAILY_SALARY))
                pressure = b / max(1.0, sal)
                scarcity = req / max(1.0, supply)
                opp_pressures.append((pressure, scarcity, b, opp))

    if not alive_opps:
        return min(budget, 18.0)

    slots = supply / float(WATER_REQ)
    alive_count = len(alive_opps) + 1
    scarcity_ratio = alive_count / max(0.5, slots)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water >= 2:
        danger += 3
    elif no_water == 1:
        danger += 1
    if scarcity_ratio >= 2.8:
        danger += 2
    elif scarcity_ratio >= 2.1:
        danger += 1
    if day >= 8:
        danger += 1

    rich_aggressive = 0
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid')
        if b is None:
            continue
        if float(b) >= 0.9 * float(opp.get('daily_salary', DAILY_SALARY)):
            rich_aggressive += 1

    if danger >= 5:
        target = max(62.0, highest_prev + 6.0, avg_prev + 8.0)
    elif danger >= 3:
        target = max(44.0, min(78.0, highest_prev + 2.5), avg_prev + 3.0)
    else:
        if rich_aggressive >= 2 and highest_prev >= 90.0:
            target = 8.0
        elif highest_prev >= 140.0:
            target = 10.0
        elif highest_prev >= 90.0:
            target = 14.0
        elif highest_prev >= 50.0:
            target = 24.0
        else:
            target = max(22.0, avg_prev * 0.75 + 3.0)

    if supply <= 16.0:
        target += 8.0
    elif supply >= 23.0 and danger <= 2:
        target -= 4.0

    if budget < target:
        if danger >= 4:
            target = budget
        else:
            target = min(budget, max(0.0, budget * 0.55))

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if danger <= 2:
        reserve_floor = min(budget, days_left * 10.0)
    elif danger == 3:
        reserve_floor = min(budget, days_left * 6.0)

    bid = min(budget - reserve_floor, target) if budget > reserve_floor else min(budget, target)
    if danger >= 4:
        bid = max(bid, min(budget, 63.0 if hp <= 2 or no_water >= 2 else 52.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    healthy = hp > 3

    # Get previous traces from alive opponents
    alive_opponents = [opp for opp in opponents_status.values() if opp['alive']]
    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    # Emergency if no water days > 1 or hp <= 0
    if no_water_days > 1 or hp <= 0:
        base = DAILY_SALARY * 0.95
    elif hp <= 2:
        base = DAILY_SALARY * 0.8
    elif healthy:
        base = DAILY_SALARY * 0.5
    else:
        base = DAILY_SALARY * 0.6

    # Adjust based on opponents' previous max bid
    if prev_bids:
        max_prev = max(prev_bids)
        # If they were very aggressive, we might need to match or exceed
        if max_prev > DAILY_SALARY * 0.85:
            if hp <= 2:
                bid = max(base, max_prev * 0.9)
            else:
                bid = max(base, max_prev * 0.75)
        else:
            bid = max(base, max_prev * 1.1)
    else:
        bid = base

    # Cap at budget and ensure not below 0
    bid = max(0, min(budget, bid))

    # On last day or high HP, maybe bid less
    if day >= 9 and hp > 5:
        bid = min(bid, DAILY_SALARY * 0.3)

    return int(bid)
